namespace MDPro3.BattleSpirits{using MDPro3.BattleSpirits.Core;public sealed class BattleCardVisual{public int width=100,height=200,left=0,top=0,right=100,bottom=200;public bool isBoss;}public static class BattleCatalog{public static bool TryGet(string id,out CardDefinition d){d=new();if(id=="nexus"){d.IsSpirit=false;d.IsNexus=true;}return id!="missing";}public static string CardImagePath(string id)=>id+".png";public static string StandeePath(string id)=>id=="nexus"?null:id+"-standee.png";public static BattleCardVisual GetVisual(string id)=>new();public static bool IsBoss(string id)=>id=="26RBS03-X01"||id=="26RBS03-022";}}
